import{_ as s,o as t,c as i,a2 as e}from"./chunks/framework.DoCD98hS.js";const c=JSON.parse('{"title":"改造应用模板","description":"","frontmatter":{},"headers":[],"relativePath":"guide/adapt-template.md","filePath":"guide/adapt-template.md","lastUpdated":1795182147000}'),p={name:"guide/adapt-template.md"};function n(l,a,h,d,o,r){return t(),i("div",null,[...a[0]||(a[0]=[e(`<h1 id="改造应用模板" tabindex="-1">改造应用模板 <a class="header-anchor" href="#改造应用模板" aria-label="Permalink to &quot;改造应用模板&quot;">​</a></h1><p>已有后台可以保留现有菜单、权限、路由与状态，只替换各项目重复使用的组件。先挑一处容易验证的能力，例如导航按钮、公共表单或弹窗。</p><h2 id="_1-明确你使用的模板交付方式" tabindex="-1">1. 明确你使用的模板交付方式 <a class="header-anchor" href="#_1-明确你使用的模板交付方式" aria-label="Permalink to &quot;1. 明确你使用的模板交付方式&quot;">​</a></h2><p>在<a href="./../modules/templates.html">应用模板</a>选择框架和 UI 库。在线演示用于体验功能；开始改造时，在你自己的应用或可编辑的模板源码副本中操作。只有编译后的静态页面时，可以预览和部署，无法从中直接修改业务源码。</p><h2 id="_2-拆分应用入口" tabindex="-1">2. 拆分应用入口 <a class="header-anchor" href="#_2-拆分应用入口" aria-label="Permalink to &quot;2. 拆分应用入口&quot;">​</a></h2><p>以有路由的 Vue 3 后台为例：把原来 <code>main.ts</code> 中引入 App、插件、全局样式、router 和 store 的代码迁到 <code>loadApp.ts</code>。新 <code>main.ts</code> 负责<a href="./getting-started.html#_2-在应用入口预加载">共享 Vue 并预加载首屏组件</a>。</p><p>如果模板需要等待首个路由，把原来的挂载改成：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// loadApp.ts：在 app.use(router) 之后</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ready</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> router.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">isReady</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">then</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> app.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mount</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;#app&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><p>在 <code>main.ts</code> 的预加载选项中使用 <code>loadApp: () =&gt; import(&#39;./loadApp&#39;).then(app =&gt; app.ready)</code>。这样首屏路由完成时才撤掉启动遮罩。已有启动动画的模板可以继续用自己的动画。</p><h2 id="_3-在业务页面替换导入" tabindex="-1">3. 在业务页面替换导入 <a class="header-anchor" href="#_3-在业务页面替换导入" aria-label="Permalink to &quot;3. 在业务页面替换导入&quot;">​</a></h2><p>按组件文档确认框架、参数、事件和样式要求，再将本地引用改为公开包入口。以上面的磁吸按钮为例：</p><div class="language-diff vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">diff</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">- import MagneticButton from &#39;@/components/MagneticButton.vue&#39;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+ import { MagneticButton } from &#39;@melt-js/comps-vue3&#39;</span></span></code></pre></div><p>页面继续传参、监听事件；登录、权限和业务数据仍由应用处理。如果新组件只在用户打开弹窗后使用，则改用<a href="./loading.html#低频组件懒加载">懒加载</a>，无需加进首屏依赖。</p><h2 id="_4-验证你的应用" tabindex="-1">4. 验证你的应用 <a class="header-anchor" href="#_4-验证你的应用" aria-label="Permalink to &quot;4. 验证你的应用&quot;">​</a></h2><p>用项目原有的构建命令生成页面，打开首页和一个深链接，试用替换过的组件。检查首次导航、回退、刷新及主题样式是否保持正常；在 Network 面板确认远程资源来自配置的托管入口。再用不可达的测试地址验证应用是否显示清楚的启动错误。</p><p>如果你的应用有多个子应用，继续阅读<a href="./micro-frontend-tabs.html">接入远程 Tab</a>，按微前端框架选择挂载和保活方式。</p>`,16)])])}const g=s(p,[["render",n]]);export{c as __pageData,g as default};
